"""Everyday spoken Taiwan Mandarin sentences generated by a local model, for what open data lacks.

The generator is MediaTek-Research/Breeze-7B-Instruct-v1_0 (Apache-2.0, no terms on its
output), converted to GGUF and served by llama.cpp's llama-server on this machine. Each request
asks for 20 short sentences for one (topic, situation) pair; the grid and the seed make the run
reproducible up to sampling.

Kept are sentences that
  * have 6-40 characters, mostly Han;
  * have no Simplified characters: a character OpenCC's s2t would change that never occurs in
    the --charset texts (real Taiwan text; s2tw itself also rewrites valid 台, 布, 了...);
  * use no mainland spellings or words (TaiwanUsage.h variants plus MAINLAND_WORDS);
  * are not duplicates, also after removing punctuation and spaces;
  * contain no evaluation segment (--exclude).
Output: sentences.txt (one per line), raw.txt (every line the model wrote, so the filters can be
rerun) and provenance.json (model file hash, prompt, settings).

  llama-server -m Breeze-7B-Instruct-v1_0-Q8_0.gguf -ngl 99 -c 16384 -np 8 --port 8091
  uv run python gen_synthetic.py ../data/raw/free/synthetic --model-file <gguf> --target 30000
"""

import argparse
import concurrent.futures
import hashlib
import itertools
import json
import random
import re
import sys
import urllib.request
from pathlib import Path

from opencc import OpenCC

ROOT = Path(__file__).resolve().parent.parent

TOPICS = [
    "早餐與便利商店", "夜市小吃", "手搖飲料", "做菜與食譜", "餐廳訂位與點餐", "外送", "超市與量販店",
    "網購與退貨", "買衣服", "3C 產品與手機", "電腦當機與軟體", "網路與 Wi-Fi", "社群貼文", "遊戲",
    "追劇與電影", "音樂與演唱會", "看書", "運動健身", "籃球與棒球", "爬山與露營", "騎腳踏車",
    "捷運與公車", "高鐵與火車", "開車與停車", "機車", "計程車", "颱風與天氣", "地震",
    "租屋與搬家", "房貸與買房", "裝潢與修理", "打掃家裡", "寵物", "照顧小孩", "長輩與家人",
    "感冒看醫生", "牙醫", "健保與藥局", "上班與加班", "開會與報告", "請假", "找工作與面試",
    "薪水與年終", "考試與讀書", "上課與作業", "補習班", "大學生活", "社團", "畢業典禮",
    "生日與聚餐", "婚禮", "過年", "中秋節", "端午節", "出國旅遊", "國內旅遊與住宿", "機場與護照",
    "銀行與轉帳", "信用卡", "繳費", "郵局與包裹", "里長與社區", "垃圾車與資源回收", "選舉與投票",
    "環保與節能", "咖啡店", "美髮", "交友與約會", "朋友之間的抱怨", "道歉與感謝", "問路",
    "客服電話", "公司同事聊天", "LINE 群組", "宗教與廟會", "農業與水果", "海邊與夏天",
]
SITUATIONS = [
    "傳給朋友的訊息", "和家人的對話", "和同事的對話", "對店員或客服說的話", "網路上的留言",
    "自言自語或日記", "老師或主管說的話", "電話裡說的話", "向陌生人詢問", "講給長輩聽的話",
]
PROMPT = """請用台灣人日常說話的口吻，寫 20 句和「{topic}」有關、屬於「{situation}」的句子。
要求：
- 使用台灣的正體中文用字與用語。
- 每句 8 到 30 個字，要像真的會打在手機上的句子，內容彼此不同。
- 可以有口語詞（像是「欸」、「啦」、「喔」），但不要用注音文或英文縮寫。
- 每行一句，不要編號，不要加其他說明。"""

# Words common in mainland usage with other words in Taiwan (Taiwan form in comments).
MAINLAND_WORDS = [
    "視頻", "軟件", "硬件", "信息", "網絡", "默認", "鼠標", "屏幕", "打印", "博客", "出租車",
    "質量", "文件夾", "U盤", "優盤", "短信", "激活", "數據庫", "程序員", "互聯網", "服務器",
    "智能手機", "土豆", "西紅柿", "自行車", "盒飯", "塑料", "公交", "靠譜", "牛逼", "給力",
    "酸奶", "方便面", "冰淇凌", "高考", "本科", "研究生院", "醫保", "社保", "微信", "支付寶",
    "淘寶", "抖音", "快遞小哥", "點贊", "充電寶", "移動電話", "攝像頭", "菜單欄", "登錄",
    "視屏", "早上好", "晚上好", "老鐵", "小區", "物業", "地鐵站",
]
TAIWAN_USAGE_H = ROOT / "src/Core/include/llaime/TaiwanUsage.h"
HAN = re.compile(r"[一-鿿]")
NOT_TEXT = re.compile(r"[\s\W_]+")
NUMBERING = re.compile(r"^\s*(\d+[\.\)、．]|[-*•])\s*")


def variant_words() -> list[str]:
    text = TAIWAN_USAGE_H.read_text(encoding="utf-8")
    return [m.group(1) for m in re.finditer(r'\{L"([^"]+)", L"[^"]+"\}', text)]


def ask(url: str, prompt: str, seed: int, temperature: float) -> str:
    body = json.dumps({
        "messages": [{"role": "user", "content": prompt}],
        "temperature": temperature, "top_p": 0.95, "seed": seed, "max_tokens": 1200,
    }).encode()
    request = urllib.request.Request(url + "/v1/chat/completions", data=body,
                                     headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(request, timeout=600) as response:
        return json.load(response)["choices"][0]["message"]["content"]


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("output", type=Path, help="directory")
    parser.add_argument("--model-file", type=Path, required=True, help="the GGUF being served")
    parser.add_argument("--server", default="http://127.0.0.1:8091")
    parser.add_argument("--target", type=int, default=30000, help="sentences to keep")
    parser.add_argument("--parallel", type=int, default=8)
    parser.add_argument("--temperature", type=float, default=0.9)
    parser.add_argument("--exclude", type=Path, nargs="*", default=[], help="evaluation TSVs")
    parser.add_argument("--charset", type=Path, nargs="+", required=True,
                        help="Taiwan Traditional texts whose characters count as Traditional")
    parser.add_argument("--seed", type=int, default=20261020)
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)

    s2t = OpenCC("s2t")
    traditional = set()
    for path in args.charset:
        traditional.update(path.read_text(encoding="utf-8"))

    def simplified(sentence: str) -> bool:
        return any(c not in traditional and s2t.convert(c) != c for c in sentence)
    banned = variant_words() + MAINLAND_WORDS
    held_out = set()
    for path in args.exclude:
        for line in path.read_text(encoding="utf-8").splitlines():
            parts = line.split("\t")
            if len(parts) >= 3:
                held_out.add(parts[2])

    jobs = list(itertools.product(TOPICS, SITUATIONS))
    rng = random.Random(args.seed)
    rng.shuffle(jobs)
    # Each round goes over the whole grid once with new seeds, until the target is reached.
    rounds = itertools.count()
    kept, seen, rejected = [], set(), {"length": 0, "simplified": 0, "mainland": 0,
                                       "duplicate": 0, "held_out": 0}

    def keep(line: str) -> None:
        sentence = NUMBERING.sub("", line).strip().strip("「」\"")
        han = len(HAN.findall(sentence))
        if not 6 <= len(sentence) <= 40 or han < 0.6 * len(sentence):
            rejected["length"] += 1
        elif simplified(sentence):
            rejected["simplified"] += 1
        elif any(w in sentence for w in banned):
            rejected["mainland"] += 1
        elif (key := NOT_TEXT.sub("", sentence)) in seen:
            rejected["duplicate"] += 1
        elif any(h in sentence for h in held_out if len(h) <= len(sentence)):
            rejected["held_out"] += 1
        else:
            seen.add(key)
            kept.append(sentence)

    raw = (args.output / "raw.txt").open("w", encoding="utf-8", newline="\n")
    with concurrent.futures.ThreadPoolExecutor(args.parallel) as pool:
        for r in rounds:
            futures = {pool.submit(ask, args.server, PROMPT.format(topic=t, situation=s),
                                   args.seed + r * len(jobs) + i, args.temperature): (t, s)
                       for i, (t, s) in enumerate(jobs)}
            for done, future in enumerate(concurrent.futures.as_completed(futures), 1):
                try:
                    for line in future.result().splitlines():
                        if line.strip():
                            raw.write(line.strip() + "\n")
                            keep(line)
                except Exception as e:  # noqa: BLE001 - one failed request is skipped
                    print(f"request failed: {e}", file=sys.stderr)
                if done % 50 == 0:
                    print(f"round {r} {done}/{len(jobs)}: kept {len(kept)} rejected {rejected}",
                          flush=True)
                if len(kept) >= args.target:
                    for f in futures:
                        f.cancel()
                    break
            if len(kept) >= args.target:
                break

    raw.close()
    (args.output / "sentences.txt").write_text("\n".join(kept) + "\n", encoding="utf-8")
    digest = hashlib.sha256()
    with args.model_file.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 24), b""):
            digest.update(chunk)
    (args.output / "provenance.json").write_text(json.dumps({
        "generator": "MediaTek-Research/Breeze-7B-Instruct-v1_0 (Apache-2.0)",
        "model_file": args.model_file.name, "model_sha256": digest.hexdigest(),
        "prompt": PROMPT, "topics": TOPICS, "situations": SITUATIONS,
        "temperature": args.temperature, "seed": args.seed,
        "kept": len(kept), "rejected": rejected,
    }, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"kept {len(kept)}, rejected {rejected}")


if __name__ == "__main__":
    main()
